package com.maryvellous.lavablobs;

import com.maryvellous.lavablobs.audio.BloopMaterialBank;
import com.maryvellous.lavablobs.audio.MaterialAudioEngine;
import org.junit.Test;
import java.util.List;
import java.util.Random;
import static org.junit.Assert.*;

/**
 * Reproduces a filled vessel with REAL 24-node membranes under buoyancy,
 * including micro-motion generated by the FIVE physical solver passes.
 * This is not an invented/constant input trace.
 */
public class MaterialAudioRealSolverTest {
    private static BloopMaterialBank bank() {
        BloopMaterialBank.Material[] parts=new BloopMaterialBank.Material[4];
        for(int j=0;j<4;j++){
            float[] complete=new float[20000],attack=new float[1000],tail=new float[4000];
            for(int k=0;k<complete.length;k++)
                complete[k]=(float)(.25*Math.sin(k*.09));
            for(int k=0;k<attack.length;k++)
                attack[k]=(float)(.2*Math.sin(k*.15)*Math.sin(Math.PI*k/(attack.length-1)));
            for(int k=0;k<tail.length;k++)
                tail[k]=(float)(.18*Math.sin(k*.07)*Math.sin(Math.PI*k/(tail.length-1)));
            parts[j]=new BloopMaterialBank.Material(complete,attack,tail);
        }
        return new BloopMaterialBank(parts);
    }

    @Test public void realRestingVesselDoesNotProduceConstantTailDrone() {
        BlobWorld world=new BlobWorld(new Random(691));
        world.setHeight(850f);
        // A dense top row: actual overlapping soft membranes, not
        // distant sprites that simply drift apart after settling.
        world.blobs.add(new Blob(67f,192f,1,1f));
        world.blobs.add(new Blob(115f,193f,2,1f));
        world.blobs.add(new Blob(168f,193f,3,1f));
        world.blobs.add(new Blob(235f,198f,4,1f));
        world.blobs.add(new Blob(306f,194f,1,1f));
        world.blobs.add(new Blob(352f,192f,2,1f));
        world.blobs.add(new Blob(175f,256f,2,1f));
        world.blobs.add(new Blob(268f,268f,3,1f));
        world.ensureBlobIds();
        // Let blobs drift and settle against their physical glass boundary.
        for(int frame=0;frame<240;frame++)world.tick(1f/60f);

        MaterialAudioEngine audio=new MaterialAudioEngine(bank());
        final int[] observations={0},peakContactPairs={0};
        final float[] peakSlip={0},peakApproach={0};
        world.setContactProbe(new ContactProbe.Listener(){
            @Override public void onContactStep(float time,float dt,
                    List<ContactProbe.Contact> samples){
                peakContactPairs[0]=Math.max(peakContactPairs[0],samples.size());
                for(ContactProbe.Contact c:samples){
                    observations[0]++;
                    peakSlip[0]=Math.max(peakSlip[0],c.slideSpeed);
                    peakApproach[0]=Math.max(peakApproach[0],c.approachSpeed);
                    audio.contact(c.blobA,c.blobB,c.approachSpeed,c.slideSpeed,
                            c.compression,c.radiusA,c.radiusB,dt);
                }
            }
            @Override public void onMerge(BlobWorld.Merge m) {
                audio.merge(m.parentAId,m.parentBId,m.radius);
            }
            @Override public void onPop(int blobId,float time){audio.cancelBlob(blobId);}
        });
        float[] mixed=new float[735]; // exactly 1/60th of 44.1 kHz
        float maxPeak=0f;
        for(int frame=0;frame<240;frame++){
            world.tick(1f/60f);
            audio.renderMono(mixed,0,mixed.length);
            for(float v:mixed)maxPeak=Math.max(maxPeak,Math.abs(v));
        }
        System.out.printf("SETTLED_SOLVER_FIXTURE observationCount=%d maxSimultaneousPairs=%d peakSlip=%.1f peakApproach=%.1f squish=%d impacts=%d%n",
                observations[0],peakContactPairs[0],peakSlip[0],peakApproach[0],
                audio.squishEvents(),audio.impactEvents());
        assertTrue("Fixture requires actual solver contact observations",observations[0]>60);
        assertTrue("Fixture requires at least one concurrent physical pair",peakContactPairs[0]>0);
        System.out.printf("REAL_SETTLED_VESSEL observations=%d peakPairs=%d peakSlip=%.1f peakApproach=%.1f squishes=%d impacts=%d peakPCM=%.5f%n",
                observations[0],peakContactPairs[0],peakSlip[0],peakApproach[0],
                audio.squishEvents(),audio.impactEvents(),maxPeak);
        // A resting vessel can still have brief infrequent physical shuffles;
        // sustained loop-generated sound is forbidden. This conservative
        // threshold will be tightened based on measured gameplay traces.
        assertTrue("Too many sound gestures in apparently resting vessel: "+
                audio.squishEvents(),audio.squishEvents()<=2);
    }
}
